for (const it of (((task.result || [])[0] || {}).items || [])) {
  const o = (it.metrics || {}).organic || {};
  etv[String(it.target).toLowerCase()] = o.count ? Number(o.etv || 0) : null; // DataForSEO lowercases targets
}
for (const r of state.results) r.etv = etv[r.url.toLowerCase()] ?? null;
