  let raw = String(resp.text || '').trim();
  if (raw.startsWith(FENCE)) raw = raw.replace(/^[^\n]*\n/, '').split(FENCE)[0];
  // With response format json_object the chain already returns the parsed object.
  labels = Array.isArray(resp.intents) ? resp : JSON.parse(raw);
  if (!Array.isArray(labels.intents) || !labels.intents.length) throw new Error('no intents in the answer');
} catch (e) {
  s.error = 'model: ' + (typeof resp.error === 'string' ? resp.error : (resp.error && resp.error.message) || e.message);
