labels.intents.forEach(it => it.result_ids.forEach(id => (k[id] = (k[id] || 0) + 1)));
const trafficTotal = s.results.filter(r => r.etv != null).reduce((a, r) => a + r.etv, 0);
const n = s.results.length;
const nearest = (arr, p) => (arr.length ? arr[Math.max(0, Math.min(arr.length - 1, Math.ceil(p / 100 * arr.length) - 1))] : null);
const rows = labels.intents.map(it => {
  const pages = it.result_ids.map(id => byId[id]);
  const words = pages.filter(p => p.fetch_status === 'ok').map(p => p.words).sort((a, b) => a - b);
  return {
    title: it.title || '', intent_type: it.intent_type || '', searcher_goal: it.searcher_goal || '', form: it.form || '', evidence: it.evidence || '', fallback: !!it.fallback,
    coverage: it.result_ids.length / n, share: it.result_ids.reduce((a, id) => a + 1 / k[id], 0) / n,
    traffic: trafficTotal ? it.result_ids.reduce((a, id) => a + (byId[id].etv || 0) / k[id], 0) / trafficTotal : null,
    ranks: pages.map(p => p.rank).sort((a, b) => a - b), words, median_words: nearest(words, 50), result_ids: it.result_ids
  };
});
const real = rows.filter(r => !r.fallback);
const top = real.slice().sort((a, b) => b.share - a.share || (b.traffic || 0) - (a.traffic || 0))[0];
const w = top ? top.words : [];
let basis = 'median_of_dominant_intent_pages';
if (w.length < 3) basis = 'insufficient_sample';
else if (w[w.length - 1] / w[0] > 50) basis = 'spread_too_wide';
const reliable = basis === 'median_of_dominant_intent_pages';
const warnings = [];
if (top && top.share < 0.4 && top.coverage < 0.5) warnings.push('mixed_serp');
if (real.filter(r => r.share >= 0.15).length >= 3) warnings.push('consider_separate_pages');
const byTraffic = real.filter(r => r.traffic != null).sort((a, b) => b.traffic - a.traffic)[0];
if (byTraffic && top && byTraffic !== top) warnings.push('traffic_disagrees');
if (labels.article_fits && labels.article_fits.value === false) warnings.push('serp_does_not_want_an_article');
if (missing.length) warnings.push('unassigned_results');
s.labels = labels;
s.rows = rows;
s.decision = {
  dominant: top ? top.title : '', form: top ? top.form : '', share: top ? top.share : null,
  length: reliable ? nearest(w, 50) : null, basis, genre: reliable ? (labels.expected_genre || '') : '',
  article_fits: labels.article_fits ? labels.article_fits.value : null, warnings
};
return [{ json: s }];

// Response for the caller: decision first, then intents and results. Unknown numbers stay null.
const s = $input.first().json;
const c = s.cost || {};
const dfs = (c.serp || 0) + (c.pages || 0) + (c.volume || 0) + (c.traffic || 0);
const r6 = v => (v == null ? null : Math.round(v * 1e6) / 1e6);
return [{ json: {
  keyword: s.keyword, location_name: s.location_name, language_name: s.language_name, model: $('Config [HTTP]').first().json.model,
  ok: !s.error, error: s.error || null,
  decision: s.decision || null, summary: (s.labels && s.labels.summary) || null, demand: s.demand || null,
  intents: (s.rows || []).map(r => ({ title: r.title, intent_type: r.intent_type, searcher_goal: r.searcher_goal, form: r.form, coverage: r.coverage, share: r.share, traffic_share: r.traffic, ranks: r.ranks, median_words: r.median_words ?? null, evidence: r.evidence })),
  results: (s.results || []).map(r => ({ rank: r.rank, url: r.url, title: r.title, domain: r.domain, words: r.words, fetch_status: r.fetch_status, etv: r.etv, elements: r.elements, intents: (s.rows || []).filter(x => x.result_ids.includes(r.result_id)).map(x => x.title) })),
  serp_features: s.features,
  cost_usd: { dataforseo: r6(dfs), openrouter: r6(c.model || 0), total: r6(dfs + (c.model || 0)), steps: c },
